/**
 * India: states & union territories, cities and towns (every district headquarters plus
 * other significant towns), and localities of the big cities.
 *
 * Stored in the regions table ("emirates", internal name) and the localities table.
 * Localities inside a city are stored as "<Locality>, <City>" (e.g. "Andheri, Mumbai")
 * so they read unambiguously in state lists; cities are flagged is_main_area.
 * There is deliberately no division/district level: a region holds its cities directly.
 * Where two states have a town of the same name, the smaller one carries a "(State)" suffix,
 * as "Udaipur (Tripura)" already did, so every slug stays unique.
 *
 * nameAr holds the local-language (Hindi, Devanagari) name (the field name comes from the
 * database schema, shared with the Arabic-script countries). It is left out where the
 * Hindi spelling is uncertain.
 * Region slugs/codes/names and the original city and locality names are kept exactly as in the live data.
 */
import type { Region } from "../country";

type City = { name: string; nameAr?: string; localities?: string[] };
type RegionDef = { slug: string; code: string; name: string; nameAr: string; capital?: boolean; territory?: boolean; cities: City[] };

